  function ecologyRule(){return ecologyRules()[0]||{dayMs:18000,seasonDays:10,maxCatchupDays:80,initialPopulationFactor:.72,searchPressure:2,failedTakePressure:4,takePressure:8,overQuotaPressure:5,basePressureDecay:5,closureRatio:.18,fragileRatio:.35,stableRatio:.72,quotaFactor:.24,overQuotaReputationLoss:1,overQuotaWardenTrustLoss:1};}
