  function ecologyCalendar(at=now()){const rule=ecologyRule(),dayMs=Math.max(1000,Number(rule.dayMs||18000)),seasonDays=Math.max(1,Number(rule.seasonDays||10)),elapsed=Math.max(0,Number(at)-calendarAnchor()),absoluteDay=Math.floor(elapsed/dayMs),seasonIndex=Math.floor(absoluteDay/seasonDays),seasons=seasonDefs().length?seasonDefs():[{id:'spring',name:'Printemps',icon:'🌱'},{id:'summer',name:'Été',icon:'☀️'},{id:'autumn',name:'Automne',icon:'🍂'},{id:'winter',name:'Hiver',icon:'❄️'}],season=seasons[seasonIndex%seasons.length]||seasons[0];return{absoluteDay,dayInSeason:absoluteDay%seasonDays+1,seasonIndex,seasonKey:season?.id||['spring','summer','autumn','winter'][seasonIndex%4],seasonName:season?.name||'Saison',seasonIcon:season?.icon||'🗓️',year:Math.floor(seasonIndex/seasons.length)+1,dayMs,seasonDays};}
  function ensureEcology(){const E=H.ecology;if(!E.populations||typeof E.populations!=='object')E.populations={};if(!E.groundPressure||typeof E.groundPressure!=='object')E.groundPressure={};const cal=ecologyCalendar();if(!Number.isFinite(Number(E.lastDay)))E.lastDay=cal.absoluteDay;for(const g of grounds()){if(!E.populations[g.id]||typeof E.populations[g.id]!=='object')E.populations[g.id]={};if(!Number.isFinite(Number(E.groundPressure[g.id])))E.groundPressure[g.id]=0;for(const spId of (g.speciesIds||[])){const cap=Math.max(0,Number(g.populationCaps?.[spId]||0));if(cap<=0)continue;const cur=E.populations[g.id][spId];if(!cur||typeof cur!=='object'){const count=cap*Number(ecologyRule().initialPopulationFactor||.72);E.populations[g.id][spId]={count,harvestedSeason:0,seasonKey:cal.seasonKey,lastStatus:'',lastUpdateDay:cal.absoluteDay};}else{cur.count=clamp(Number(cur.count||0),0,cap);if(!Number.isFinite(Number(cur.harvestedSeason)))cur.harvestedSeason=0;if(!cur.seasonKey)cur.seasonKey=cal.seasonKey;}}}return E;}
  function populationState(groundId,speciesId){const E=ensureEcology(),g=ground(groundId),cap=Math.max(0,Number(g?.populationCaps?.[speciesId]||0));if(!g||cap<=0)return null;if(!E.populations[groundId]?.[speciesId])ensureEcology();return E.populations[groundId]?.[speciesId]||null;}
  function populationRatio(groundId,speciesId){const g=ground(groundId),cap=Math.max(.001,Number(g?.populationCaps?.[speciesId]||0)),ps=populationState(groundId,speciesId);return ps?clamp(Number(ps.count||0)/cap,0,1):0;}
  function populationStatus(groundId,speciesId){const ratio=populationRatio(groundId,speciesId),sp=species(speciesId),rule=ecologyRule(),closure=Math.max(Number(rule.closureRatio||.18),Number(sp?.criticalRatio||0));if(ratio<=closure)return{id:'critical',name:'Fermeture',icon:'⛔',ratio};if(ratio<Number(rule.fragileRatio||.35))return{id:'fragile',name:'Fragile',icon:'⚠️',ratio};if(ratio<Number(rule.stableRatio||.72))return{id:'stable',name:'Stable',icon:'🌿',ratio};return{id:'thriving',name:'Abondante',icon:'🌱',ratio};}
  function seasonQuota(groundId,speciesId){const g=ground(groundId),cap=Math.max(0,Number(g?.populationCaps?.[speciesId]||0)),sp=species(speciesId),cal=ecologyCalendar(),breeding=Number(sp?.seasonBreeding?.[cal.seasonKey]||1),factor=Number(ecologyRule().quotaFactor||.24)*(breeding>=1.2?1.12:breeding<.4?.76:1);return Math.max(1,Math.round(cap*factor));}
