  function seasonalActivity(groundId,sp){const cal=ecologyCalendar(),g=ground(groundId),b=biome(g?.biomeId);return Math.max(.08,Number(sp?.seasonActivity?.[cal.seasonKey]||1)*Number(sp?.biomeAffinity?.[g?.biomeId]||1)*(1+Number(b?.trackModifier||0)));}
  function applyManualHarvest(groundId,speciesId){const ps=populationState(groundId,speciesId),sp=species(speciesId),g=ground(groundId),rule=ecologyRule();if(!ps||!sp||!g)return;ps.count=clamp(Number(ps.count||0)-1,0,Number(g.populationCaps?.[speciesId]||0));ps.harvestedSeason=Number(ps.harvestedSeason||0)+1;addPressure(groundId,Number(rule.takePressure||8));const quota=seasonQuota(groundId,speciesId);if(ps.harvestedSeason<=quota){S.stats.sustainableHarvests++;}else{S.stats.overQuotaHarvests++;addPressure(groundId,Number(rule.overQuotaPressure||5));S.reputation=clamp(S.reputation-Number(rule.overQuotaReputationLoss||1));if(typeof S.clientTrust?.hunter_warden==='number')S.clientTrust.hunter_warden=clamp(S.clientTrust.hunter_warden-Number(rule.overQuotaWardenTrustLoss||1));C.log(`⚠️ Quota conseillé dépassé pour ${sp.name.toLowerCase()} à ${g.name} : réputation et confiance du garde se dégradent.`);} }

  function knowledgeStage(id){if(Number(H.speciesEncounters[id]||0)<=0&&Number(H.knowledge[id]||0)<=0)return -1;const sp=species(id),xp=Number(H.knowledge[id]||0)/Math.max(.55,Number(sp?.knowledgeDifficulty||1));let lvl=0;for(let i=1;i<K_THRESH.length;i++)if(xp>=K_THRESH[i])lvl=i;return Math.min(3,lvl);}
  function knowledgeLevel(id){return Math.max(0,knowledgeStage(id));}
  function knowledgeProgress(id){const stage=knowledgeStage(id),sp=species(id),raw=Number(H.knowledge[id]||0),xp=raw/Math.max(.55,Number(sp?.knowledgeDifficulty||1));if(stage<0)return{stage:-1,raw,xp,pct:0,next:K_THRESH[1],name:'Inconnue'};const next=stage>=3?null:K_THRESH[stage+1],base=K_THRESH[stage],pct=next===null?100:clamp((xp-base)/(next-base)*100);return{stage,raw,xp,pct,next,name:K_NAMES[stage]};}
