  function gainKnowledge(id,n){if(!id||!Number(n||0))return;const before=knowledgeStage(id);H.knowledge[id]=Number(H.knowledge[id]||0)+Number(n||0);S.stats.knowledgeXpEarned+=Number(n||0);const after=knowledgeStage(id);if(after>before&&after>=1)C.log(`📚 ${species(id)?.name||'Espèce'} : connaissance ${K_NAMES[after]}.`);if(after>=3&&!H.masteredSpecies.includes(id)){H.masteredSpecies.push(id);S.stats.masteredSpecies=H.masteredSpecies.length;C.log(`🎓 ${species(id)?.name||'Espèce'} est désormais maîtrisé dans le carnet du Chasseur.`);}}
