  function skillProgress(id){const xp=Number(H.skillXp[id]||0),lvl=skillLevel(id),max=Number(skillDef(id)?.maxLevel||10),next=lvl>=max?null:SKILL_THRESH[lvl],base=SKILL_THRESH[Math.max(0,lvl-1)]||0,pct=next===null?100:clamp((xp-base)/(next-base)*100);return{xp,lvl,max,next,pct};}
  function gainSkill(id,n){if(!id||!Number(n||0))return;H.skillXp[id]=Number(H.skillXp[id]||0)+Number(n||0);S.stats.skillXpEarned+=Number(n||0);}
  function phaseTechniques(phase){return techniques().filter(t=>t.phase===phase);}
  function techniqueUnlocked(t,spId=''){if(!t||S.level<Number(t.minLevel||1)||skillLevel(t.skillId)<Number(t.minSkill||1))return false;if(t.phase!=='search'&&Number(t.minKnowledge||0)>0){if(!spId||knowledgeLevel(spId)<Number(t.minKnowledge||0))return false;}return true;}
  function selectedTechnique(phase,spId=''){let t=technique(H.selectedTechnique[phase]);if(t&&t.phase===phase&&techniqueUnlocked(t,spId))return t;const open=phaseTechniques(phase).filter(x=>techniqueUnlocked(x,spId)).sort((a,b)=>Number(b.minSkill||1)-Number(a.minSkill||1));t=open[0]||phaseTechniques(phase)[0]||null;if(t)H.selectedTechnique[phase]=t.id;return t;}
