  function gearEffect(key){return Object.values(H.equippedGear||{}).map(id=>hunterGear(id)?.effects?.[key]).filter(v=>v!==undefined).reduce((n,v)=>n+Number(v||0),0);}
  function primarySpec(){return specDef(H.specialization.primary);} function talentIds(){return H.specialization.talents||[];}
