  function sealUnlocked(id){return S.masterySeals.includes(id);}function sealEffect(key){return masterySealDefs().filter(x=>sealUnlocked(x.id)).reduce((n,x)=>n+Number(x.effects?.[key]||0),0);}function careerEffect(key){return S.masterCertified?Number(masterCareer()?.effects?.[key]||0):0;}
  function specEffect(key){return talentIds().map(id=>talentDef(id)?.effects?.[key]).filter(v=>v!==undefined).reduce((n,v)=>n+Number(v||0),0)+sealEffect(key)+careerEffect(key);}
  function phaseToolEffect(phase,key){const t=equippedTool(phase);if(!t||toolCondition(t.id)<=0)return 0;return Number(t[key]||0)*toolFactor(t.id)+(key==='qualityBonus'?toolMastery(t.id)*.35:0);}
  function phaseDuration(base,phase){const t=equippedTool(phase),eff=t?Math.max(.58,Number(t.efficiency||1)*toolFactor(t.id)):1,red=specEffect(`${phase}DurationReduction`);return Math.max(1,Number(base||1)/eff*(1-Math.min(.35,red)));}
