  function effectText(effects={}){const labels={searchChance:'Recherche',trackQuality:'Qualité piste',searchEnergyReduction:'Énergie pistage',knowledgeGain:'Connaissance',freshness:'Fraîcheur',searchDurationReduction:'Vitesse pistage',marketBonus:'Marché',approachSuccess:'Approche',alertReduction:'Vigilance',takeSuccess:'Prélèvement',safety:'Sécurité',takeQuality:'Qualité prélèvement',approachDurationReduction:'Vitesse approche',prepareQuality:'Préparation',meatYield:'Rendement viande',secondaryYield:'Matières secondaires',premiumSale:'Prime Q75+',contractReward:'Contrats',prepareDurationReduction:'Vitesse préparation'};return Object.entries(effects||{}).map(([k,v])=>{const pct=['searchChance','searchEnergyReduction','knowledgeGain','searchDurationReduction','marketBonus','approachSuccess','takeSuccess','safety','approachDurationReduction','meatYield','secondaryYield','premiumSale','contractReward','prepareDurationReduction'].includes(k);return `${labels[k]||k} ${Number(v)>=0?'+':''}${pct?Math.round(Number(v)*100)+'%':Number(v)}`;});}

