  function availableSpecies(g){processEcology();return (g?.speciesIds||[]).map(species).filter(x=>x&&!x.exceptionalOnly&&S.level>=Number(x.minLevel||1)&&Number(populationState(g.id,x.id)?.count||0)>.15).map(x=>Object.assign({},x,{weight:Number(x.weight||1)*Math.max(.08,populationRatio(g.id,x.id))*seasonalActivity(g.id,x)}));}

