    wearTool('search',.8);H.current={id:`hunt_${++H.seq}`,stage:'trail',groundId:g.id,speciesId:sp.id,trackQuality:quality,freshness,alert:clamp(rand(22,42)+Math.round((difficulty-1)*15)),approachId:'',searchTechniqueId:t?.id||'',approachTechniqueId:'',takeTechniqueId:'',prepareTechniqueId:'',takeQuality:0,startedAt:now()};S.stats.tracksFound++;gainSkill('tracking',2);C.gainJobXp(JOB,4);C.gainMastery(JOB,1);C.log(`${sp.icon} Piste de ${sp.name} repérée — qualité ${Math.round(quality)}/100 · savoir ${knowledgeProgress(sp.id).name}.`);
