  function exceptionalRequirement(def){const cal=ecologyCalendar(),sp=species(def?.speciesId),ps=populationState(def?.groundId,def?.speciesId),ratio=def?populationRatio(def.groundId,def.speciesId):0,rows=[];const add=(label,ok,detail)=>rows.push({label,ok:!!ok,detail});if(!def)return rows;add('Niveau',S.level>=Number(def.minLevel||1),`${S.level}/${def.minLevel||1}`);add('Grade',rankOrder()>=Number(def.minRank||0),`${rankOrder()}/${def.minRank||0}`);add('Réputation',S.reputation>=Number(def.minReputation||0),`${Math.round(S.reputation)}/${def.minReputation||0}`);add('Connaissance',knowledgeLevel(def.speciesId)>=Number(def.minKnowledge||0),`${knowledgeLevel(def.speciesId)}/${def.minKnowledge||0}`);if(def.seasons?.length)add('Saison',def.seasons.includes(cal.seasonKey),cal.seasonName);if(Number(def.minPopulationRatio||0)>0)add('Population rare',ratio>=Number(def.minPopulationRatio),`${Math.round(ratio*100)}% / ${Math.round(Number(def.minPopulationRatio)*100)}%`);if(def.preySpeciesId&&Number(def.minPreyRatio||0)>0){const r=populationRatio(def.groundId,def.preySpeciesId);add('Population de proies',r>=Number(def.minPreyRatio),`${Math.round(r*100)}% / ${Math.round(Number(def.minPreyRatio)*100)}%`);}for(const id of def.requiresCompleted||[])add(`Traque : ${exceptional(id)?.name||id}`,Number(H.exceptional.completed[id]||0)>0,Number(H.exceptional.completed[id]||0)>0?'acquise':'requise');if(sp?.predator&&ps)add('Prédateur présent',Number(ps.count||0)>=.45,`${Math.round(Number(ps.count||0)*10)/10} individu(s)`);return rows;}
