  function resolveExceptionalSighting(){if(H.task||H.current?.stage!=='sighting')return;const def=exceptional(H.current.exceptionalHuntId),sp=species(H.current.speciesId);if(!def||def.resolution==='harvest'||!sp)return;const cost=def.resolution==='drive'?10:6;if(!spendEnergy(cost)){C.log('✨ Énergie insuffisante pour conclure proprement cette opération.');return render();}const field=skillLevel('fieldcraft'),track=Number(H.current.trackQuality||50),alert=Number(H.current.alert||30),k=knowledgeLevel(sp.id),base=def.resolution==='drive'?.62:.78,p=base+(field-1)*.018+k*.045+(track-60)/250-alert/420+specEffect('approachSuccess');if(chance(p)){if(def.resolution==='drive'){addPressure(def.groundId,5);const ps=populationState(def.groundId,def.speciesId);if(ps)ps.count=clamp(Number(ps.count||0)-.12,0,Number(ground(def.groundId)?.populationCaps?.[def.speciesId]||0));}gainKnowledge(sp.id,5);gainSkill('fieldcraft',4);completeExceptional(def.id,Math.round(clamp(track-alert*.15+field*3+k*4,50,100)),def.resolution);H.current=null;}else{gainKnowledge(sp.id,2);gainSkill('fieldcraft',2);addPressure(def.groundId,4);H.exceptional.cooldowns[def.id]=now()+Math.round(Number(def.leadCooldown||60)*650);C.log(`🌫️ ${def.name} : l’opération échoue sans incident, mais l’animal disparaît. Il faudra retrouver des signes.`);H.current=null;}C.save();render();}
