  function qualityLabel(q){return q>=90?'Exceptionnelle':q>=80?'Excellente':q>=68?'Soignée':q>=55?'Correcte':'Rustique';}

  function rankOrder(){return Number(S.rankOrder||0);}
  function hunterClients(){return (C.content.jobClients||[]).filter(c=>c.jobId===JOB).sort((a,b)=>Number(a.minRank||0)-Number(b.minRank||0));}
  function hunterContracts(){return (C.content.jobContracts||[]).filter(c=>c.jobId===JOB);}
  function reputationTiers(){return (C.content.hunterReputationTiers||[]).slice().sort((a,b)=>Number(a.minReputation||0)-Number(b.minReputation||0));}
  function currentRepTier(){return reputationTiers().filter(x=>S.reputation>=Number(x.minReputation||0)).pop()||reputationTiers()[0]||{name:'Pisteur local',effects:{}};}
  function clientTrust(id){return clamp(Number(S.clientTrust?.[id]||0),0,100);}
  function clientStatus(v){return v>=70?'Partenaire fidèle':v>=45?'Confiance établie':v>=25?'Habitué':v>=10?'Connaissance':'Nouveau commanditaire';}
  function rankName(order){return C.professionalRanks(JOB).find(r=>Number(r.order||0)===Number(order||0))?.name||`Grade ${order}`;}
  function knowledgeCountAt(level){return speciesDefs().filter(sp=>knowledgeLevel(sp.id)>=Number(level||1)).length;}
  function trustedClientCount(threshold){return hunterClients().filter(c=>clientTrust(c.id)>=Number(threshold||0)).length;}
  function skillAverage(){return skills().length?skills().reduce((n,x)=>n+skillLevel(x.id),0)/skills().length:1;}
  function aggregateEffects(){const out={};const add=e=>{for(const [k,v] of Object.entries(e||{}))out[k]=Number(out[k]||0)+Number(v||0);};add(currentRepTier()?.effects);for(const c of hunterClients())for(const perk of c.trustPerks||[])if(clientTrust(c.id)>=Number(perk.minTrust||0))add(perk.effects);for(const id of talentIds())add(talentDef(id)?.effects);for(const seal of masterySealDefs())if(sealUnlocked(seal.id))add(seal.effects);if(S.masterCertified)add(masterCareer()?.effects);return out;}
  function rankRequirements(rank){const req=rank?.requirements||{},rows=[],add=(label,have,need)=>{if(Number(need||0)>0)rows.push({label,have:Number(have||0),need:Number(need||0),ok:Number(have||0)>=Number(need||0)});};add('Niveau du métier',S.level,rank?.minLevel||1);add('Niveau du village',C.state.level,rank?.minVillageLevel||1);const map={searches:'Sorties de pistage',successfulHunts:'Prélèvements réussis',prepared:'Prises préparées',bestQuality:'Meilleure qualité',remarkableContracts:'Livraisons remarquables'};for(const [k,label] of Object.entries(map))add(label,S.stats[k]||0,req[k]);add('Contrats réussis',S.completedContracts,req.contractsCompleted);add('Réputation métier',S.reputation,req.reputation);if(Number(req.trustedClients||0)>0)add(`Commanditaires à confiance ≥ ${req.trustThreshold||0}`,trustedClientCount(req.trustThreshold||0),req.trustedClients);add('Pistage',skillLevel('tracking'),req.skillTracking);add('Discrétion',skillLevel('fieldcraft'),req.skillFieldcraft);add('Prélèvement',skillLevel('marksmanship'),req.skillMarksmanship);add('Préparation',skillLevel('field_dressing'),req.skillDressing);if(Number(req.knowledgeCount||0)>0)add(`Espèces ≥ ${K_NAMES[Number(req.knowledgeLevel||1)]||req.knowledgeLevel}`,knowledgeCountAt(req.knowledgeLevel||1),req.knowledgeCount);return rows;}
  function canPromote(){const next=C.nextProfessionalRank(JOB);return !!next&&rankRequirements(next).every(r=>r.ok);}
  window.hunterPromote=()=>{const next=C.nextProfessionalRank(JOB);if(!next||!canPromote())return;C.promoteJob(JOB);C.gainVillageXp(8+Number(next.order||0)*4);C.log(`🎖️ Promotion Chasseur : ${next.name}. De nouveaux commanditaires et contrats deviennent accessibles.`);S.lastContractRefresh=0;C.evaluateAchievements?.(false);C.save();render();};
  function criteria(def){return def?.hunterCriteria||{};}
  function hasCriteria(def){const c=criteria(def);return Number(c.qualityMin||0)>0||Number(c.knowledgeMin||0)>0||(c.speciesIds||[]).length||(c.preparationIds||[]).length||!!c.activeOnly;}
  function lotCompatible(lot,def){const c=criteria(def);return (!c.activeOnly||lot.source==='hunter')&&(!(c.speciesIds||[]).length||(c.speciesIds||[]).includes(lot.speciesId))&&(!(c.preparationIds||[]).length||(c.preparationIds||[]).includes(lot.preparationId))&&Number(lot.quality||0)>=Number(c.qualityMin||0)&&Number(lot.knowledgeLevel||0)>=Number(c.knowledgeMin||0);}
