  function criteriaText(def){const c=criteria(def),bits=[];if((c.speciesIds||[]).length)bits.push(`Espèce : ${(c.speciesIds||[]).map(id=>species(id)?.name||id).join(' / ')}`);if((c.preparationIds||[]).length)bits.push(`Préparation : ${(c.preparationIds||[]).map(id=>prep(id)?.name||id).join(' / ')}`);if(Number(c.qualityMin||0)>0)bits.push(`Qualité ≥ Q${c.qualityMin}`);if(Number(c.knowledgeMin||0)>0)bits.push(`Savoir ≥ ${K_NAMES[c.knowledgeMin]||c.knowledgeMin}`);if(c.activeOnly)bits.push('Prise active traçable');return bits.join(' · ')||'Stock courant accepté';}
  function consumeForContract(def,qty){qty=Math.max(0,Number(qty||0));if(!hasCriteria(def)){if(!C.consumeResource(def.resourceId,qty,'Livraison contrat Chasseur'))return null;return{avgQuality:0};}let remaining=qty,qualitySum=0,used=0;const lots=C.state.materialLots?.[def.resourceId];if(!Array.isArray(lots)||compatibleContractQty(def)+1e-9<qty)return null;for(const l of lots){if(remaining<=1e-9)break;if(!lotCompatible(l,def))continue;const take=Math.min(remaining,Number(l.quantity||0));l.quantity=Math.max(0,Number(l.quantity||0)-take);remaining-=take;used+=take;qualitySum+=take*Number(l.quality||0);}if(remaining>1e-9)return null;C.state.materialLots[def.resourceId]=lots.filter(l=>Number(l.quantity||0)>1e-9);C.state.resources[def.resourceId]=Math.max(0,C.resource(def.resourceId)-qty);C.recordInventoryEvent('out',def.resourceId,qty,'Livraison contrat Chasseur');return{avgQuality:used?qualitySum/used:0};}
  function contractRemarkable(def,delivered){const min=Number(criteria(def).qualityMin||0);return !!delivered&&min>0&&Number(delivered.avgQuality||0)>=Math.max(75,Math.min(98,min+7));}
  function contractEligible(def){if(!def)return false;processEcology();const c=C.jobClient(def.clientId),wanted=criteria(def).speciesIds||[],ecologyOk=!wanted.length||wanted.some(spId=>grounds().some(g=>(g.speciesIds||[]).includes(spId)&&harvestAllowed(g.id,spId)));return (!def.requiresMaster||S.masterCertified)&&(!c?.masterOnly||S.masterCertified)&&rankOrder()>=Number(def.minRank||0)&&S.level>=Number(def.minLevel||1)&&S.reputation>=Number(def.minReputation||0)&&clientTrust(def.clientId)>=Number(def.minTrust||0)&&(!c||rankOrder()>=Number(c.minRank||0))&&ecologyOk;}
  function activeContractLimit(){return (rankOrder()>=3?3:2)+Math.max(0,Math.round(Number(aggregateEffects().activeContractSlots||0)));}
  function offerLimit(){return 4+Math.max(0,Math.round(Number(aggregateEffects().offerSlots||0)));}
  function cleanupOffers(){const t=now();S.contractOffers=S.contractOffers.filter(o=>Number(o.expiresAt||0)>t);}
  function generateContractOffers(force=false){cleanupOffers();const t=now();if(!force&&t-Number(S.lastContractRefresh||0)<12000)return;S.lastContractRefresh=t;const occupied=new Set([...S.contractOffers,...S.activeContracts].map(x=>x.contractId)),pool=hunterContracts().filter(d=>contractEligible(d)&&!occupied.has(d.id));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}while(S.contractOffers.length<offerLimit()&&pool.length){const d=pool.shift();S.contractOffers.push({id:`hunter_offer_${++H.seq}`,contractId:d.id,createdAt:t,expiresAt:t+90000});}}
  function failContract(active,reason='Délai dépassé'){const d=C.jobContract(active.contractId);if(!d)return;const f=d.failure||{};S.reputation=clamp(S.reputation-Number(f.reputation||0));S.clientTrust[d.clientId]=clamp(clientTrust(d.clientId)-Number(f.trust||0));S.failedContracts++;S.contractHistory.unshift({contractId:d.id,status:'failed',at:now(),reason});S.contractHistory=S.contractHistory.slice(0,50);C.log(`❌ Contrat Chasseur échoué — ${d.name}. ${reason}.`);}
