  window.hunterAcceptContract=id=>{const o=S.contractOffers.find(x=>x.id===id),d=C.jobContract(o?.contractId);if(!o||!d||!contractEligible(d)||S.activeContracts.length>=activeContractLimit())return;const deadline=1+Number(aggregateEffects().deadlineBonus||0);S.contractOffers=S.contractOffers.filter(x=>x.id!==id);S.activeContracts.push({id:`hunter_contract_${++H.seq}`,contractId:d.id,acceptedAt:now(),end:now()+Number(d.duration||240)*1000*deadline});C.log(`📜 Contrat Chasseur accepté : ${d.name}.`);C.save();render();};
