  window.hunterAbandonContract=id=>{const a=S.activeContracts.find(x=>x.id===id);if(!a)return;failContract(a,'Contrat abandonné');S.activeContracts=S.activeContracts.filter(x=>x.id!==id);S.lastContractRefresh=0;C.save();render();};
  window.hunterDeliverContract=id=>{const a=S.activeContracts.find(x=>x.id===id),d=C.jobContract(a?.contractId);if(!a||!d||compatibleContractQty(d)<Number(d.quantity||1))return;const delivered=consumeForContract(d,Number(d.quantity||1));if(!delivered)return;const remarkable=contractRemarkable(d,delivered),fx=aggregateEffects(),bonus=(remarkable?1.18:1)*(1+Number(fx.contractReward||0)),reward=d.reward||{},treasury=Math.round(Number(reward.treasury||0)*bonus),trustGain=(Number(reward.trust||0)+(remarkable?1:0))*(1+Number(fx.trustGain||0));C.gainJobXp(JOB,Math.round(Number(reward.jobXp||0)*bonus));C.gainVillageXp(Math.round(Number(reward.villageXp||0)*bonus));C.gainMastery(JOB,remarkable?4:2);S.reputation=clamp(S.reputation+Number(reward.reputation||0)+(remarkable?2:0));S.clientTrust[d.clientId]=clamp(clientTrust(d.clientId)+trustGain);C.state.treasury=Math.max(0,Number(C.state.treasury||0)+treasury);S.completedContracts++;S.stats.contractRevenue+=treasury;if(remarkable)S.stats.remarkableContracts++;if(d.requiresMaster)S.stats.prestigeContracts++;S.contractHistory.unshift({contractId:d.id,status:'delivered',at:now(),remarkable,avgQuality:delivered.avgQuality,treasury});S.contractHistory=S.contractHistory.slice(0,50);S.activeContracts=S.activeContracts.filter(x=>x.id!==id);S.lastContractRefresh=0;C.log(`${remarkable?'⭐ Livraison remarquable':'📦 Contrat livré'} : ${d.name} · réputation ${Math.round(S.reputation)}/100 · ${treasury} couronnes.`);C.evaluateAchievements?.(false);C.save();render();};

  window.hunterBuyTool=id=>{const t=hunterTool(id);if(!t||ownsTool(id)||S.level<Number(t.level||1)||!rankAllows(t.minRank)||Number(C.state.treasury||0)<Number(t.price||0))return;C.state.treasury-=Number(t.price||0);H.ownedTools.push(id);H.toolCondition[id]=toolMax(id);H.toolXp[id]=0;H.equippedTools[t.operation]=id;S.stats.toolsBought++;S.stats.equipmentSpent+=Number(t.price||0);C.log(`🧰 Équipement Chasseur acheté : ${t.name}.`);C.evaluateAchievements?.(false);C.save();render();};
  window.hunterEquipTool=id=>{const t=hunterTool(id);if(!t||!ownsTool(id))return;H.equippedTools[t.operation]=id;C.log(`🧰 ${t.name} équipé pour ${t.operation}.`);C.save();renderEquipment();renderMetrics();};
  window.hunterRepairTool=id=>{const t=hunterTool(id),cost=repairCost(id);if(!t||!ownsTool(id)||toolCondition(id)>=toolMax(id)-.01||Number(C.state.treasury||0)<cost)return;C.state.treasury-=cost;H.toolCondition[id]=toolMax(id);S.stats.maintenanceSpent+=cost;C.log(`🔧 ${t.name} remis en état pour ${cost} couronnes.`);C.save();render();};
  window.hunterBuyGear=id=>{const g=hunterGear(id);if(!g||ownsGear(id)||S.level<Number(g.level||1)||!rankAllows(g.minRank)||Number(C.state.treasury||0)<Number(g.price||0))return;C.state.treasury-=Number(g.price||0);H.ownedGear.push(id);H.equippedGear[g.slot]=id;S.stats.gearBought++;S.stats.equipmentSpent+=Number(g.price||0);C.log(`🎒 Équipement Chasseur acheté : ${g.name}.`);C.save();render();};
  window.hunterEquipGear=id=>{const g=hunterGear(id);if(!g||!ownsGear(id))return;H.equippedGear[g.slot]=id;C.log(`🎒 ${g.name} équipé.`);C.save();renderEquipment();renderMetrics();};
  window.hunterChooseSpecialization=id=>{const sp=specDef(id);if(!sp||H.specialization.primary||S.level<Number(sp.minLevel||5)||!rankAllows(sp.minRank||2))return;H.specialization.primary=id;C.log(`🧭 Spécialisation choisie : ${sp.name}. Cette voie devient l'orientation principale du Chasseur.`);C.save();render();};
  window.hunterUnlockTalent=id=>{const sp=primarySpec(),talent=(sp?.talents||[]).find(t=>t.id===id);if(!sp||!talent||talentIds().includes(id)||specializationPointsFree()<Number(talent.cost||1)||!(talent.requires||[]).every(x=>talentIds().includes(x)))return;H.specialization.talents.push(id);S.stats.specializationTalents=H.specialization.talents.length;C.log(`✨ Talent Chasseur acquis : ${talent.name}.`);C.evaluateAchievements?.(false);C.save();render();};
  window.hunterSellLoose=(id,all=false)=>{refreshMarket();const m=marketItem(id),have=Math.floor(looseQty(id));if(!m||have<1)return;const qty=all?have:1,total=Math.round(looseSalePrice(id)*qty*100)/100;C.state.resources[id]=Math.max(0,C.resource(id)-qty);C.recordInventoryEvent('out',id,qty,'Vente marché Chasseur — stock courant');C.state.treasury=Number(C.state.treasury||0)+total;S.stats.marketSales+=qty;S.stats.marketRevenue+=total;H.marketDemand[id]=clamp(marketDemand(id)-qty*.01,Number(m.minDemand||.7),Number(m.maxDemand||1.5));C.log(`🪙 ${qty} ${m.name.toLowerCase()} vendu(s) pour ${total.toFixed(2)} couronnes.`);C.evaluateAchievements?.(false);C.save();render();};
  window.hunterSellLot=(resourceId,lotId)=>{refreshMarket();const lots=C.state.materialLots?.[resourceId]||[],lot=lots.find(l=>l.id===lotId&&l.source==='hunter'),m=marketItem(resourceId);if(!lot||!m)return;const reservations=lotContractReservations(resourceId,lot);if(reservations.length){C.log(`📜 Lot conservé : il est nécessaire à ${reservations.map(d=>d.name).join(' / ')}.`);return renderEconomy();}const qty=Number(lot.quantity||0),total=lotSalePrice(resourceId,lot);C.state.materialLots[resourceId]=lots.filter(l=>l.id!==lotId);C.state.resources[resourceId]=Math.max(0,C.resource(resourceId)-qty);C.recordInventoryEvent('out',resourceId,qty,'Vente marché Chasseur — lot qualitatif');C.state.treasury=Number(C.state.treasury||0)+total;S.stats.marketSales+=qty;S.stats.marketRevenue+=total;H.marketDemand[resourceId]=clamp(marketDemand(resourceId)-qty*.012,Number(m.minDemand||.7),Number(m.maxDemand||1.5));C.log(`🪙 Lot de ${m.name.toLowerCase()} Q${Math.round(lot.quality||0)} vendu pour ${total.toFixed(2)} couronnes.`);C.evaluateAchievements?.(false);C.save();render();};
  function primaryCapstoneDone(){const sp=primarySpec(),ids=talentIds();if(!sp)return false;const cap=(sp.talents||[]).find(t=>(t.requires||[]).length>=2)||(sp.talents||[]).slice(-1)[0];return !!cap&&ids.includes(cap.id);}
  function exceptionalUniqueCount(){return Object.keys(H.exceptional.completed||{}).filter(id=>Number(H.exceptional.completed[id]||0)>0).length;}
  function masteredCommonSpecies(){return ['hare','pheasant','roe_deer','wild_boar'].filter(id=>knowledgeLevel(id)>=3).length;}
  function healthyCommonGrounds(){return ['forest_edge','river_meadow','thorn_scrub'].filter(id=>ground(id)&&groundPopulationScore(id)>=.50&&groundPressure(id)<=50).length;}
